const a=await recoverEditedSculptAsset(source,{expectedSha256:sha});
const world={id:'C2C_Asset_001',x:8,z:8,scale:.7,rotation:.31,groundAt:(x,z)=>({y:4+.025*x+.012*z}),waterAt:()=>null,projectWorld:p=>({...p}),protectedFootprints:Object.values(protectedBounds),worldBounds:{xMin:-180,xMax:100,zMin:-330,zMax:100}};
const place=o=>groundEditedAsset(a,{...world,...o});
const makesHost=()=>{const history=[],live=new Set();return {history,live,beginTransaction:(id,mesh,receipt)=>{history.push('stage');assert.equal(mesh.indices.length,receipt.triangles*3);return {commit:()=>{history.push('commit');live.add(id);},draw:packet=>{assert(live.has(id));history.push('draw');return packet.tick;},rollback:()=>{history.push('rollback');live.delete(id);}};}};};

test('correct exact-main edit hash and topology return source-bound native geometry',()=>{assert.equal(a.metadata.saveSha256,sha);assert.equal(a.metadata.topologyStages,1);assert.equal(a.metadata.triangles,906);assert.equal(a.metadata.masterVertices,455);assert.equal(a.metadata.vertices,463);});
test('invalid source SHA is rejected before reconstruction',async()=>{await assert.rejects(()=>recoverEditedSculptAsset(source,{expectedSha256:'0'.repeat(64)}),/SOURCE_SHA256_MISMATCH/);});
test('malformed JSON fails closed',async()=>{await assert.rejects(()=>recoverEditedSculptAsset('{'.repeat(110)),/SAVE_JSON_INVALID/);});
test('rejects neutral-only mesh and non-image source',async()=>{const j=JSON.parse(source);j.stages=[];await assert.rejects(()=>recoverEditedSculptAsset(JSON.stringify(j)),/NOT_EDITED_IMAGE_DERIVED_SOURCE/);});
test('rejects forged source stage through admitted session restoration',async()=>{const j=JSON.parse(source);const st=JSON.parse(j.stages[0].recipe);st.sourceId='UNTRUSTED';j.stages[0].recipe=JSON.stringify(st);await assert.rejects(()=>recoverEditedSculptAsset(JSON.stringify(j)));});
test('source mesh snapshot copies cannot mutate underlying geometry',()=>{const s=a.snapshot(),v=s.positions[0];s.positions[0]=5000;s.uvs[0]=NaN;s.indices[0]=65535;assert.equal(a.snapshot().positions[0],v);assert(Number.isFinite(a.snapshot().uvs[0]));assert.notEqual(a.snapshot().indices[0],65535);});
test('world projection gives exact intact triangle/UV index counts',()=>{const p=place(),m=p.snapshot();assert.equal(p.receipt.triangles,906);assert.equal(m.indices.length,2718);assert.equal(m.positions.length/3,463);assert.equal(m.uvs.length/2,463);assert.equal(m.normals.length/3,463);assert(m.worldPositions.every(Number.isFinite));});
test('world projected vertex positions reflect actual supplied world projection',()=>{const p=place({projectWorld:v=>({x:v.x+1000,y:v.y+100,z:v.z-1000})}),m=p.snapshot();assert(Math.abs((m.positions[0]-m.worldPositions[0])-1000)<.0001);assert(Math.abs((m.positions[1]-m.worldPositions[1])-100)<.0001);});
test('source material UV values are bitwise intact through world handoff',()=>{const src=a.snapshot(),out=place().snapshot();assert.deepEqual([...src.uvs],[...out.uvs]);assert.deepEqual([...src.indices],[...out.indices]);});
test('world payload is copy-protected across snapshots',()=>{const p=place(),a=p.snapshot(),z=a.positions[0];a.positions[0]=NaN;a.indices[0]=65535;assert.equal(p.snapshot().positions[0],z);assert.notEqual(p.snapshot().indices[0],65535);});
test('footprint ground sampling uses one center plus four rotated corners',()=>{let calls=[];const p=place({groundAt:(x,z)=>{calls.push([x,z]);return {y:5};}});assert.equal(calls.length,5);assert.equal(p.receipt.groundContacts.length,5);});
test('nominal world insert does not intersect protected accepted tree bounds',()=>{const p=place();assert(p.receipt.worldFootprint.minX>7);assert.equal(p.receipt.terrainSource,'HOST_WORLD_SAMPLER');});
test('all eight accepted tree placements fail protection guard',()=>{assert.equal(RECORDED_SITES.length,8);for(const r of RECORDED_SITES)assert.throws(()=>place({x:r.x,z:r.z}),/PROTECTED_WORLD_COLLISION/,r.id);});
test('unknown or unauthorized world boundary fails',()=>{assert.throws(()=>place({x:400}),/OUTSIDE_AUTHORIZED_REGION/);});
test('missing ground support fails closed',()=>{assert.throws(()=>place({groundAt:()=>null}),/GROUND_CONTACT_MISSING/);});
test('submerged ground or standing water fails closed',()=>{assert.throws(()=>place({groundAt:()=>({y:5}),waterAt:()=>({y:5})}),/WATER_INTERSECTION/);});
test('incomplete corner support fails closed',()=>{let c=0;assert.throws(()=>place({groundAt:()=>++c===3?null:{y:5}}),/GROUND_CONTACT_MISSING/);});
test('steep footprint fails closed',()=>{assert.throws(()=>place({groundAt:(x,z)=>({y:5+3*x})}),/FOOTPRINT_SLOPE_UNSUPPORTED/);});
test('negative or gigantic world scale fails closed',()=>{assert.throws(()=>place({scale:-1}),/TRANSFORM_INVALID/);assert.throws(()=>place({scale:10}),/TRANSFORM_INVALID/);});
test('nonfinite world projection fails closed',()=>{assert.throws(()=>place({projectWorld:()=>({x:Infinity,y:0,z:0})}),/PROJECTED_WORLD_POINT_INVALID/);});
test('missing host contract fails closed',()=>{assert.throws(()=>createReversibleWorldHandoff(place(),{}),/HOST_TRANSACTION_REQUIRED/);});
test('successful attach -> draw -> detach -> double detach is deterministic',()=>{const host=makesHost(),o=createReversibleWorldHandoff(place(),host);assert.equal(o.status(),'PREPARED');assert.equal(o.attach(),true);assert.equal(o.draw({tick:8}),8);assert.equal(o.detach(),true);assert.equal(o.detach(),false);assert.deepEqual(host.history,['stage','commit','draw','rollback']);assert.equal(host.live.size,0);});
test('duplicate attachment rejected before any host change',()=>{const host=makesHost(),o=createReversibleWorldHandoff(place(),host);o.attach();assert.throws(()=>o.attach(),/ATTACH_STATE_INVALID/);assert.equal(host.live.size,1);o.detach();});
test('bad transaction contract rolls back before adoption',()=>{let roll=0;const host={beginTransaction:()=>({rollback:()=>roll++})};const o=createReversibleWorldHandoff(place(),host);assert.throws(()=>o.attach(),/HOST_TRANSACTION_CONTRACT_INVALID/);assert.equal(o.status(),'QUARANTINED');assert.equal(roll,1);});
test('commit error rolls back previous state and quarantines',()=>{let roll=0;const host={beginTransaction:()=>({commit:()=>{throw Error('COMMIT_FAULT')},rollback:()=>roll++,draw:()=>{}})};const o=createReversibleWorldHandoff(place(),host);assert.throws(()=>o.attach(),/COMMIT_FAULT/);assert.equal(roll,1);assert.equal(o.status(),'QUARANTINED');});
test('draw error rolls back and quarantines',()=>{let roll=0;const host={beginTransaction:()=>({commit:()=>{},rollback:()=>roll++,draw:()=>{throw Error('DRAW_FAULT')}})};const o=createReversibleWorldHandoff(place(),host);o.attach();assert.throws(()=>o.draw({}),/DRAW_FAULT/);assert.equal(roll,1);assert.equal(o.status(),'QUARANTINED');});
test('detach error quarantines rather than falsely reporting clean removal',()=>{const host={beginTransaction:()=>({commit:()=>{},rollback:()=>{throw Error('ROLLBACK_FAULT')},draw:()=>{}})};const o=createReversibleWorldHandoff(place(),host);o.attach();assert.throws(()=>o.detach(),/ROLLBACK_FAULT/);assert.equal(o.status(),'QUARANTINED');});
test('world transaction cannot draw before attach',()=>{const o=createReversibleWorldHandoff(place(),makesHost());assert.throws(()=>o.draw({}),/DRAW_STATE_INVALID/);});
